1840   * copy_word
  1841   * copies the next 'token' from 'from' into 'to', maximum len-1 characters.
  1842   * currently a token is anything separate by white space
  1843   * or within quotes (double or single) (i.e. "the red rose"
  1844   * is one token, \"the red rose\" is three tokens)
  1845   * a '\' character will allow a quote character to be treated
  1846   * as a regular character
  1847   * It returns a pointer to first non-white space after the end of the token
  1848   * being copied or to 0 if we reach the end.
  1849   * Note: Partially copied words (greater than len) still returns a !NULL ptr
  1850   * Note: partially copied words are, however, null terminated.
  1851   */
  1852
  1853  char           *
  1854  copy_nword(char *from, char *to, int len)
  1855  {
  1856      return NETSNMP_REMOVE_CONST(char *, copy_nword_const(from, to, len));
  1857  }
