  1859  const char           *
  1860  copy_nword_const(const char *from, char *to, int len)
  1861  {
  1862      char            quote;
  1863      if (!from || !to)
  1864          return NULL;
  1865      if ((*from == '\"') || (*from == '\'')) {
  1866          quote = *(from++);
  1867          while ((*from != quote) && (*from != 0)) {
  1868              if ((*from == '\\') && (*(from + 1) != 0)) {
  1869                  if (len > 0) {  /* don't copy beyond len bytes */
  1870                      *to++ = *(from + 1);
  1871                      if (--len == 0)
  1872                          *(to - 1) = '\0';       /* null protect the last spot */
  1873                  }
  1874                  from = from + 2;
  1875              } else {
  1876                  if (len > 0) {  /* don't copy beyond len bytes */
  1877                      *to++ = *from++;
  1878                      if (--len == 0)
  1879                          *(to - 1) = '\0';       /* null protect the last spot */
  1880                  } else
  1881                      from++;
  1882              }
  1883          }
  1884          if (*from == 0) {
  1885              DEBUGMSGTL(("read_config_copy_word",
  1886                          "no end quote found in config string\n"));
  1887          } else
  1888              from++;
  1889      } else {
  1890          while (*from != 0 && !isspace((unsigned char)(*from))) {
  1891              if ((*from == '\\') && (*(from + 1) != 0)) {
  1892                  if (len > 0) {  /* don't copy beyond len bytes */
  1893                      *to++ = *(from + 1);
  1894                      if (--len == 0)
  1895                          *(to - 1) = '\0';       /* null protect the last spot */
  1896                  }
  1897                  from = from + 2;
  1898              } else {
  1899                  if (len > 0) {  /* don't copy beyond len bytes */
  1900                      *to++ = *from++;
  1901                      if (--len == 0)
  1902                          *(to - 1) = '\0';       /* null protect the last spot */
  1903                  } else
  1904                      from++;
  1905              }
  1906          }
  1907      }
  1908      if (len > 0)
  1909          *to = 0;
  1910      from = skip_white_const(from);
  1911      return (from);
  1912  }                               /* copy_nword */
